const metrics = $input.first().json || {};

const period = metrics.period || {};
const leads = metrics.leads || {};
const bands = Array.isArray(metrics.bands) ? metrics.bands : [];
const outreach = metrics.outreach || {};
const draftBreakdown = Array.isArray(metrics.draft_breakdown) ? metrics.draft_breakdown : [];
const queueBreakdown = Array.isArray(metrics.queue_breakdown) ? metrics.queue_breakdown : [];
const replies = Array.isArray(metrics.reply_breakdown) ? metrics.reply_breakdown : [];
const topNiches = Array.isArray(metrics.top_niches) ? metrics.top_niches : [];
const topRegions = Array.isArray(metrics.top_regions) ? metrics.top_regions : [];
const blockers = metrics.blockers || {};
const workflowHealth = Array.isArray(metrics.workflow_health) ? metrics.workflow_health : [];

function line(label, value) {
  return `${label}: ${value ?? 0}`;
}

function listRows(rows, labelKey = "niche") {
  if (!Array.isArray(rows) || rows.length === 0) return "None";
  return rows
    .map((r, i) => `${i + 1}. ${r[labelKey] || "Unknown"} — ${r.count ?? 0}`)
    .join("\n");
}

function countFromRows(rows, key, value) {
  if (!Array.isArray(rows)) return 0;
  const found = rows.find((r) => r[key] === value);
  return Number(found?.count || 0);
}

function formatBands(rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    return "None";
  }

  const knownBands = ["A", "B", "C", "D"];

  const knownLines = knownBands.map((band) => {
    const row = rows.find((r) => r.band === band);
    const count = Number(row?.count || 0);
    const avgScore = row?.avg_score ?? "n/a";
    return `${band}: ${count} lead(s), avg score ${avgScore}`;
  });

  const otherLines = rows
    .filter((r) => !knownBands.includes(r.band))
    .map((r) => `${r.band || "unknown"}: ${r.count ?? 0} lead(s), avg score ${r.avg_score ?? "n/a"}`);

  return [...knownLines, ...otherLines].join("\n");
}

function formatBreakdown(rows, key) {
  if (!Array.isArray(rows) || rows.length === 0) return "None";
  return rows
    .map((r) => `- ${r[key] || "Unknown"}: ${r.count ?? 0}`)
    .join("\n");
}

function formatWorkflowHealth(rows) {
  if (!Array.isArray(rows) || rows.length === 0) return "None";
  return rows
    .map((r) => {
      const lastSeen = r.last_seen_at ? new Date(r.last_seen_at).toISOString() : "unknown";
      return `- ${r.workflow_name || "Unknown workflow"} / ${r.status || "unknown"}: ${r.count ?? 0}, last seen ${lastSeen}`;
    })
    .join("\n");
}

const emailsSent = Number(outreach.sent || 0);
const repliesReceived = Number(outreach.replies || 0);
const replyRate = emailsSent > 0
  ? `${((repliesReceived / emailsSent) * 100).toFixed(1)}%`
  : "0%";

const positiveInterest = countFromRows(replies, "intent", "positive_interest");
const neutralQuestions = countFromRows(replies, "intent", "neutral_question");
const objections = countFromRows(replies, "intent", "objection");
const wrongPerson = countFromRows(replies, "intent", "wrong_person");
const manualReviewRequired = countFromRows(replies, "intent", "manual_review_required");
const notInterested = countFromRows(replies, "intent", "not_interested");
const unsubscribes = countFromRows(replies, "intent", "unsubscribe");
const outOfOffice = countFromRows(replies, "intent", "out_of_office");
const bounces = countFromRows(replies, "intent", "bounce");

const pendingDraftApprovals = Number(blockers.pending_draft_approvals || 0);
const pendingManualReviews = Number(blockers.pending_manual_reviews || outreach.manual_review_pending || 0);
const blockedQueueItems = Number(blockers.blocked_queue_items || 0);
const pausedQueueItems = Number(blockers.paused_queue_items || 0);
const unhandledReplies = Number(blockers.unhandled_replies || 0);

const report = `
Weekly Automation Report

Period:
${period.start_at || "Last 7 days"} → ${period.end_at || "Now"}

Lead Pipeline:
${line("Leads created", leads.total_created)}
${line("New leads", leads.new)}
${line("Enriched leads", leads.enriched)}
${line("Scored leads", leads.scored)}
${line("Queued leads", leads.queued)}
${line("Drafted leads", leads.drafted)}
${line("In sequence", leads.in_sequence)}
${line("Replied leads", leads.replied)}
${line("Blocked or paused leads", leads.blocked_or_paused)}

Band Breakdown:
${formatBands(bands)}

Outreach:
${line("Emails sent", outreach.sent)}
${line("Failed sends", outreach.failed)}
${line("Replies received", outreach.replies)}
Reply rate: ${replyRate}
${line("Manual reviews created", outreach.manual_review_created)}
${line("Manual reviews pending", outreach.manual_review_pending)}

Draft Breakdown:
${formatBreakdown(draftBreakdown, "approval_status")}

Queue Breakdown:
${formatBreakdown(queueBreakdown, "status")}

Reply Breakdown:
Positive interest: ${positiveInterest}
Neutral questions: ${neutralQuestions}
Objections: ${objections}
Wrong person: ${wrongPerson}
Manual review required: ${manualReviewRequired}
Not interested: ${notInterested}
Unsubscribe: ${unsubscribes}
Out of office: ${outOfOffice}
Bounce: ${bounces}

Top Niches:
${listRows(topNiches, "niche")}

Top Regions:
${listRows(topRegions, "region")}

Blockers:
Global outreach paused: ${blockers.global_outreach_paused === true ? "YES" : "No"}
Blocked queue items: ${blockedQueueItems}
Paused queue items: ${pausedQueueItems}
Pending draft approvals: ${pendingDraftApprovals}
Pending manual reviews: ${pendingManualReviews}
Unhandled replies: ${unhandledReplies}

Workflow Health:
${formatWorkflowHealth(workflowHealth)}

Suggested Next Actions:
${blockers.global_outreach_paused === true ? "- Global outreach is paused. Unpause only after reviewing safety settings.\n" : ""}${pendingManualReviews > 0 ? "- Clear pending manual reviews so high-value leads do not stall.\n" : ""}${pendingDraftApprovals > 0 ? "- Review pending draft approvals before the next sending window.\n" : ""}${unhandledReplies > 0 ? "- Review unhandled replies and manually take over positive-interest or manual-review leads.\n" : ""}${emailsSent === 0 ? "- No emails were sent this week. Check approved drafts, inbox capacity, and sending scheduler.\n" : ""}${blockedQueueItems > 0 ? "- Review blocked queue items to improve validation and routing rules.\n" : ""}${pausedQueueItems > 0 ? "- Review paused queue items before resuming outreach.\n" : ""}- Review replies and manually take over positive-interest or manual-review leads.

No raw reply bodies or sensitive payloads are included in this report.
`.trim();

return [
  {
    json: {
      subject: "Weekly Automation Report",
      report
    }
  }
];
